            std::println("в реестре: {}", item->name);
        }
    }

private:
    std::vector<std::unique_ptr<Item>> items_;
};

int main() {
    Registry registry;
    std::string name;
    while (std::cin >> name) {
        auto current = std::make_unique<Item>(name);
        std::println("создан {}", current->name);
        registry.adopt(std::unique_ptr<Item>(current.get()));
    }
    registry.print();
    return 0;
}

