    // Напишите решение здесь.
    return 0;
}

additionalExercises.referenceSolution:
#include <cstddef>
#include <iostream>
#include <memory>
#include <optional>
#include <print>
#include <string>
#include <utility>

struct Node {
    int value;
    std::unique_ptr<Node> next;
};

class List {
public:
    List() = default;
    List(const List &) = delete;
    List &operator=(const List &) = delete;
    ~List() {
        while (head_) {
            head_ = std::move(head_->next);
        }
    }

    void push_front(int x) {
        head_ = std::make_unique<Node>(Node{x, std::move(head_)});
        ++size_;
    }

    std::optional<int> pop_front() {
        if (!head_) {
            return std::nullopt;
        }
        const int v = head_->value;
        head_ = std::move(head_->next);
        --size_;
        return v;
    }

    void reverse() {
        std::unique_ptr<Node> prev;
        while (head_) {
            auto next = std::move(head_->next);
            head_->next = std::move(prev);
            prev = std::move(head_);
            head_ = std::move(next);
        }
        head_ = std::move(prev);
    }

    void print() const {
        std::string s;
        int shown = 0;
        for (const Node *n = head_.get(); n && shown < 10; n = n->next.get(), ++shown) {
            s += " " + std::to_string(n->value);
        }
        if (size_ > 10) {
            s += " …";
        }
        std::println("размер {}:{}", size_, s);
    }

private:
    std::unique_ptr<Node> head_;
    std::size_t size_ = 0;
};

int main() {
    List list;
    std::string command;
    while (std::cin >> command) {
        if (command == "push") {
            int x;
            std::cin >> x;
            list.push_front(x);
        } else if (command == "pop") {
            if (auto v = list.pop_front()) {
                std::println("{}", *v);
            } else {
                std::println("пусто");
            }
        } else if (command == "fill") {
            int n;
            std::cin >> n;
            for (int i = 1; i <= n; ++i) {
                list.push_front(i);
            }
        } else if (command == "reverse") {
            list.reverse();
        } else {
            list.print();
        }
    }
    return 0;
}

